<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { ApiClient, errorMessage } from '../api'
import { dateTime } from '../domain'
import type { Product, Session } from '../types'
import type { Diagnostic, IntegrationStatus, SearchResult } from './types'
const props = defineProps<{ api: ApiClient; shopId: string; sessions: Session[]; products: Product[] }>()
const diagnostics = ref<Diagnostic | null>(null), status = ref<IntegrationStatus | null>(null), error = ref(''), loading = ref(false), searchBusy = ref(false), searchError = ref(''), result = ref<SearchResult | null>(null)
const sessionId = ref(''), productId = ref(''), question = ref('')
watch(() => props.sessions, value => { if (!value.some(s => s.id === sessionId.value)) sessionId.value = value.find(s => s.status === 'active')?.id ?? '' }, { immediate: true })
watch(() => props.products, value => { if (!value.some(p => p.id === productId.value)) productId.value = value.find(p => p.active)?.id ?? '' }, { immediate: true })
async function load() { if (loading.value) return; loading.value = true; error.value = ''; const results = await Promise.allSettled([props.api.request<Diagnostic>('/diagnostics', { timeout: 70_000 }), props.api.request<IntegrationStatus>('/integrations/status')]); results.forEach((value, index) => { if (value.status === 'rejected') error.value += (error.value ? '；' : '') + errorMessage(value.reason); else if (index === 0) diagnostics.value = value.value as Diagnostic; else status.value = value.value as IntegrationStatus }); loading.value = false }
onMounted(load)
async function search() { if (!sessionId.value || !productId.value || !question.value.trim() || searchBusy.value) return; searchBusy.value = true; searchError.value = ''; result.value = null; try { result.value = await props.api.request<SearchResult>('/retrieval/search', { method: 'POST', body: { shop_id: props.shopId, session_id: sessionId.value, product_id: productId.value, question: question.value.trim() }, timeout: 60_000 }) } catch (cause) { searchError.value = errorMessage(cause) } finally { searchBusy.value = false } }
const names: Record<string, string> = { database: '数据库', deepseek: 'DeepSeek 配置', tts: '本地语音', live: '媒体服务', livetalking: '媒体服务', retrieval: '知识检索', taobao: '淘宝配置' }
</script>
<template>
  <div class="settings-grid"><section class="panel padded"><div class="section-heading"><h2>服务诊断</h2><button class="button secondary small" :disabled="loading" @click="load">{{ loading ? '检查中…' : '重新检查' }}</button></div><div v-if="error" class="alert error" role="alert">{{ error }}</div><p v-if="!diagnostics && loading" class="hint">正在检查实际配置与可达状态…</p><div v-if="diagnostics" class="diagnostic-list"><article v-for="check in diagnostics.checks" :key="check.name"><div><strong>{{ names[check.name] || check.name }}</strong><span class="badge" :class="check.status === 'ok' ? 'success' : check.status === 'failed' ? 'danger' : 'neutral'">{{ check.status === 'ok' ? '本次检查通过' : check.status === 'failed' ? '检查失败' : '未配置' }}</span></div><p>{{ check.detail }}</p></article><p class="hint">检查时间 {{ dateTime(diagnostics.checked_at) }} · {{ diagnostics.note }}</p></div><div v-if="status" class="integration-summary"><h3>淘宝消息接收</h3><p>{{ status.taobao.configured ? '后端已配置开放平台应用' : '尚未配置应用或授权' }}{{ status.taobao.shop_id && status.taobao.shop_id !== shopId ? ' · 配置绑定的是其他本地店铺' : '' }}</p><p>HTTP 拉取 · 自动轮询{{ status.taobao.polling ? '已启用' : '未启用' }} · 最近成功 {{ dateTime(status.taobao.last_success_at) }}</p><p v-if="status.taobao.last_error_code" class="danger-text">错误：{{ status.taobao.last_error_code }}</p><p class="hint">较低实时性的本地联调路径。配置或一次拉取成功都不代表淘宝直播正在播出。</p></div></section>
  <section class="panel padded"><form class="form-stack" @submit.prevent="search"><div class="section-heading"><h2>检索核对</h2><span class="badge neutral">{{ status?.retrieval.mode === 'bge' ? '配置为 BGE 语义检索' : '关键词基础模式' }}</span></div><p class="hint">使用与生成话术相同的店铺、商品、场次及有效期筛选。检索操作本身不会调用 DeepSeek。</p><label>本地场次<select v-model="sessionId" required><option value="">先创建可用场次</option><option v-for="session in sessions" :key="session.id" :value="session.id">{{ session.title }}</option></select></label><label>商品<select v-model="productId" required><option value="">先录入商品</option><option v-for="product in products" :key="product.id" :value="product.id">{{ product.title }}</option></select></label><label>核对问题<textarea v-model="question" maxlength="2000" rows="3" required placeholder="例如这件商品的退换规则是什么？" /></label><div v-if="searchError" class="alert error" role="alert">{{ searchError }}</div><button class="button primary" :disabled="searchBusy || !sessionId || !productId || !question.trim()">{{ searchBusy ? '检索中…' : '运行本地检索' }}</button></form><div v-if="result" class="search-results"><p class="hint">本次实际模式：{{ result.mode === 'bge' ? 'BGE 语义检索' : '关键词检索' }} · {{ result.note }}</p><p v-if="!result.matches.length" class="empty-state compact">没有匹配的有效资料。可到知识与记忆页补充已核验事实。</p><article v-for="match in result.matches" :key="match.id"><strong>{{ match.title }}</strong><p>{{ match.content }}</p></article></div></section></div>
</template>
